package com.shici.app.core.u1
import com.shici.app.core.*
import com.shici.app.core.b4.host.*
import org.junit.Assert.*
import org.junit.Test
import java.time.*
class U1RepositoryAcceptanceTest {
 private val now=Instant.parse("2026-10-21T12:00:00Z").toEpochMilli();private val zone=ZoneId.of("UTC")
 private fun repo()=LearningRepository(Context(),"u1-test-isolated")
 private fun entry(k:String)=DictionaryEntry(k,"n.","original $k","raw-original","v0")
 private fun plan(r:LearningRepository,keys:List<String>)=StudyMembership(StudyBook.ALL,keys){DictionaryResolver.resolve(null,r.storedEntry(it)?:entry(it),it){k->r.userEntry(k)}}
 private fun collect(r:LearningRepository,k:String,t:Long=now)=r.record(QueryEvent("q-$k-$t",k,k,k,t),entry(k))
 private fun answer(r:LearningRepository,k:String,t:Long=now){val c=r.studyView(plan(r,listOf(k)),t,zone).card!!;assertTrue(r.revealStudyCard(c.token));assertEquals(StudyCommitOutcome.COMMITTED,r.commitStudyFeedback(c.token,FeedbackKind.KNOW,t,zone))}
 @Test fun U1R01_newSupplementDoesNotCreateAnyLearningRows()=repo().use{r->val before=r.backupSnapshot();val saved=r.saveUserEntry("novel","n.","本机新词",now,newHeadword=true);assertTrue(saved.saved&&saved.changed);val d=r.backupSnapshot().data;assertTrue(d.words.isEmpty()&&d.events.isEmpty()&&d.states.isEmpty()&&d.reviews.isEmpty());assertEquals(listOf("novel"),d.userEntries.map{it.entryKey});assertEquals(before.revision+1,r.changes.version);assertTrue(r.personalMembers().isEmpty())}
 @Test fun U1R02_idempotentSaveDoesNotPublishOrDuplicate()=repo().use{r->val a=r.saveUserEntry("novel","n.","自定义",now);val rev=r.changes.version;val b=r.saveUserEntry("novel","n.","自定义",now+1,expectedUpdatedAt=now);assertTrue(b.saved);assertFalse(b.changed);assertEquals(a.entry,b.entry);assertEquals(rev,r.changes.version);assertEquals(1,r.userEntryCount())}
 @Test fun U1R03_changePreservesCommittedLearningFields()=repo().use{r->collect(r,"alpha");r.updateWord("alpha",true,"note-private");answer(r,"alpha");val before=r.backupSnapshot();assertTrue(r.saveUserEntry("alpha","v.","新释义",now).saved);val after=r.backupSnapshot();assertEquals(before.data.copy(userEntries=after.data.userEntries),after.data)}
 @Test fun U1R04_saveAdvancesRevisionAndBlocksStaleRestore()=repo().use{r->val before=r.backupSnapshot();r.saveUserEntry("alpha","","新版",now);assertEquals(RestoreOutcome.REVISION_CHANGED,r.restoreBackup(before.data,before.revision));assertEquals("新版",r.userEntry("alpha")!!.meaning)}
 @Test fun U1R05_oldEditorUpdatedAtConflicts()=repo().use{r->r.saveUserEntry("alpha","","旧",now);r.saveUserEntry("alpha","","新",now+1,expectedUpdatedAt=now);val before=r.backupSnapshot();assertFalse(r.saveUserEntry("alpha","","迟到",now+2,expectedUpdatedAt=now).saved);assertEquals(before,r.backupSnapshot())}
 @Test fun U1R06_sameMillisecondOldEditorMustNotOverwriteNewMeaning()=repo().use{r->r.saveUserEntry("alpha","","旧",now);assertTrue(r.saveUserEntry("alpha","","新",now,expectedUpdatedAt=now).saved);assertFalse("updatedAt collision authorizes stale editor",r.saveUserEntry("alpha","","迟到",now+1,expectedUpdatedAt=now).saved);assertEquals("新",r.userEntry("alpha")!!.meaning)}
 @Test fun U1R07_invalidAndBoundaryInputs()=repo().use{r->for(k in listOf("","A","two words","a\u0000")){assertFalse(k,r.saveUserEntry(k,"","m",now,newHeadword=true).saved)};for(m in listOf(" ","bad\u0001","x".repeat(16385))){assertFalse(r.saveUserEntry("alpha","",m,now).saved)};assertFalse(r.saveUserEntry("alpha","p".repeat(65),"m",now).saved);assertTrue(r.saveUserEntry("a".repeat(128),"p".repeat(64),"m".repeat(16384),now,newHeadword=true).saved);assertFalse(r.saveUserEntry("a".repeat(129),"","m",now).saved)}
 @Test fun U1R08_saveFailureRollsBackAndNoSuccess()=repo().use{r->collect(r,"alpha");val b=r.backupSnapshot();r.writableDatabase.failAt="INSERT OR REPLACE INTO user_entries";assertFalse(r.saveUserEntry("alpha","","m",now).saved);assertEquals(b,r.backupSnapshot())}
 @Test fun U1R09_saveClearsOnlyAffectedPendingNotProgress()=repo().use{r->val c=r.studyView(plan(r,listOf("alpha")),now,zone).card!!;r.revealStudyCard(c.token);r.saveUserEntry("alpha","","m",now);assertNull(r.backupSnapshot().data.session);assertEquals(StudyCommitOutcome.REJECTED,r.commitStudyFeedback(c.token,FeedbackKind.KNOW,now,zone));val n=r.studyView(plan(r,listOf("alpha")),now,zone).card!!;assertNotEquals(c.token,n.token);assertTrue(n.entry.meaning.contains("m"))}
 @Test fun U1R10_deleteLearningKeepsUserDictionaryAndBookCanRelearn()=repo().use{r->collect(r,"alpha");r.saveUserEntry("alpha","","m",now);answer(r,"alpha");assertEquals(DeleteOutcome.DELETED,r.deleteWord("alpha",r.deletions.capture()));val d=r.backupSnapshot().data;assertTrue(d.words.isEmpty()&&d.events.isEmpty()&&d.states.isEmpty()&&d.reviews.isEmpty());assertEquals("m",d.userEntries.single().meaning);assertTrue(r.studyView(plan(r,listOf("alpha")),now+1,zone).card!!.newWord)}
 @Test fun U1R11_explicitQueryOnlyMakesPersonalPriority()=repo().use{r->r.saveUserEntry("zeta","","m",now);assertTrue(r.personalMembers().isEmpty());val user=PersonalDictionary.userOnly(r.userEntry("zeta")!!);r.record(QueryEvent("qz","zeta","Zeta","zeta",now),user);collect(r,"alpha",now+1);val keys=UnifiedStudyPool.merged(r.personalMembers(),listOf("book","zeta"),listOf("six","book"));assertEquals(listOf("alpha","zeta","book","six"),keys);assertEquals("alpha",r.studyView(plan(r,keys),now+2,zone).card!!.entryKey)}
 @Test fun U1R12_allDueSurvivesSourceMembershipChangeAndWinsNew()=repo().use{r->answer(r,"orphan");val t=now+StudyRules.DAY_MILLIS;val v=r.studyView(plan(r,listOf("new")),t,zone);assertEquals("orphan",v.card!!.entryKey);assertFalse(v.card!!.newWord);assertEquals(1,v.progress.dueNow)}
 @Test fun U1R13_dueTieSortedKeyAndNoDuplicateLearning()=repo().use{r->answer(r,"beta");answer(r,"alpha");val v=r.studyView(plan(r,listOf("beta","alpha","alpha","new")),now+StudyRules.DAY_MILLIS,zone);assertEquals("alpha",v.card!!.entryKey);assertEquals(2,r.backupSnapshot().data.states.size)}
 @Test fun U1R14_userOnlyMarkerMeaningSurvivesQueryStudyAndUpdate()=repo().use{r->val text="第一义\n\n【用户补充】\n合法原文";assertTrue(r.saveUserEntry("novel","n.",text,now).saved);val stored=r.userEntry("novel")!!;assertEquals("正文合法空行不得被删除",text,stored.meaning);val e=PersonalDictionary.userOnly(stored);r.record(QueryEvent("q","novel","novel","novel",now),e);val resolved=DictionaryResolver.resolve(null,r.storedEntry("novel"),"novel"){r.userEntry(it)}!!;assertEquals(text,resolved.meaning)}
 @Test fun U1R15_repeatedBodyLinesAreDataNotDuplicateSave()=repo().use{r->val text="义项甲\n例句 X\n义项乙\n例句 X";r.saveUserEntry("alpha","",text,now);assertEquals("不得删合法正文重复行",text,r.userEntry("alpha")!!.meaning)}
 @Test fun U1R16_oldQueryAfterSupplementNeverHidesNewMeaning()=repo().use{r->val old=entry("alpha");r.saveUserEntry("alpha","","new-user",now);r.record(QueryEvent("late","alpha","alpha","alpha",now),old);val resolved=DictionaryResolver.resolve(null,r.storedEntry("alpha"),"alpha"){r.userEntry(it)}!!;assertTrue(resolved.meaning.contains("new-user"));assertTrue(resolved.meaning.contains("original alpha"));assertEquals(1,r.events().size)}
 @Test fun U1R17_noEventsSupplementRoundTripsAndFullOverwrite()=repo().use{r->r.saveUserEntry("novel","n.","m",now);val snap=r.backupSnapshot();val decoded=LearningBackupCodec.decode(LearningBackupCodec.encode(snap.data,"1.2.0",22,now));assertEquals(3,decoded.formatVersion);assertEquals(3,decoded.schemaVersion);assertFalse(decoded.noPersonalDictionary);assertEquals(snap.data,decoded.data);r.saveUserEntry("other","","other",now+1);assertEquals(RestoreOutcome.RESTORED,r.restoreBackup(decoded.data,r.changes.version));assertEquals(listOf("novel"),r.userEntries().map{it.entryKey})}
 @Test fun U1R18_overwriteOldDataClearsSupplementsNotMerge()=repo().use{r->r.saveUserEntry("local","","mine",now);assertEquals(RestoreOutcome.RESTORED,r.restoreBackup(LearningBackupData(emptyList(),emptyList()),r.changes.version));assertEquals(0,r.userEntryCount())}
 @Test fun U1R19_admissionInvalidatedBeforeUserWriteRejects()=repo().use{r->val permit=StudyAdmission();permit.invalidate();assertFalse(r.saveUserEntry("alpha","","m",now,admission=permit).saved);assertEquals(0,r.userEntryCount())}
 @Test fun U1R20_literalMarkerHistoricalSnapshotMustSurviveRecordAndBackup()=repo().use{r->
  val original=entry("alpha").copy(meaning="原始第一义\n\n【用户补充】\n原始后半义",partOfSpeech="n.；用户补充：v.")
  assertTrue(r.record(QueryEvent("q-marker","alpha","alpha","alpha",now),original));val b=LearningBackupCodec.decode(LearningBackupCodec.encode(r.backupSnapshot().data,"1.2.0",22,now));assertEquals(original.meaning,b.data.words.single().meaning);assertEquals(original.partOfSpeech,b.data.words.single().partOfSpeech)
 }
 @Test fun U1R21_restoredOriginalMarkerPlusSupplementMustNotLoseHistoricalMeaning()=repo().use{r->
  val original=entry("alpha").copy(meaning="first\n\n【用户补充】\nvalid historical tail")
  val w=BackupWord(original.key,original.headword,original.partOfSpeech,original.meaning,original.source,original.version,true,"note")
  r.restoreBackup(LearningBackupData(listOf(w),emptyList()),r.changes.version);r.saveUserEntry("alpha","","mine",now)
  val e=DictionaryResolver.resolve(null,r.storedEntry("alpha"),"alpha"){r.userEntry(it)}!!;assertTrue("historical original text lost by parsing marker",e.meaning.contains(original.meaning));assertTrue(e.meaning.contains("mine"));assertEquals(original.meaning,r.backupSnapshot().data.words.single().meaning)
 }
 @Test fun U1R22_saveDeletePendingFailureRollsBackAlreadyInsertedUser()=repo().use{r->
  r.studyView(plan(r,listOf("alpha")),now,zone);val before=r.backupSnapshot();r.database.failAt="DELETE FROM study_session"
  assertFalse(r.saveUserEntry("alpha","","new text",now).saved);assertEquals(before,r.backupSnapshot());assertNull(r.userEntry("alpha"))
 }
}
